('001', 'vista certificati presente', COALESCE((to_regclass('public.public_certificate_verification') IS NOT NULL), false))
)
  SELECT string_agg(migrazione || ': ' || controllo, E'\n' ORDER BY migrazione, controllo)
  INTO problemi FROM controlli
  WHERE migrazione IN ('001','002','003','006') AND NOT ok;
  IF problemi IS NOT NULL THEN
    RAISE EXCEPTION 'Riparazione annullata: prerequisiti strutturali non coerenti.%', E'\n' || problemi;
  END IF;

