INSERT INTO public.questionnaires (id,title,version,description,pass_percent,is_demo,is_active) VALUES ('41000000-0000-4000-8000-000000000001','Nautica da diporto · basi per la conduzione',1,'Preparazione dell’uscita, responsabilità al comando e sicurezza a bordo. Introduzione formativa, non corso abilitante né simulazione dell’esame ministeriale.',80,true,true) ON CONFLICT (id) DO NOTHING;
-- Source: https://www.mit.gov.it/temi/patenti-mezzi-abilitazioni/patenti-nautiche/normativa
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000101','41000000-0000-4000-8000-000000000001',1,'Superare questo questionario consente di ottenere una patente nautica?','["No: la patente richiede il percorso ufficiale previsto per la categoria.","Sì, basta raggiungere l’80%.","Sì, se si naviga solo nel Mediterraneo."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000101',0) ON CONFLICT (question_id) DO NOTHING;
-- Source: https://www.mit.gov.it/temi/patenti-mezzi-abilitazioni/patenti-nautiche/normativa
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000102','41000000-0000-4000-8000-000000000001',2,'Dove verificare quali requisiti servono per condurre una specifica unità in Italia?','["Nel risultato di un quiz generico online.","Nella normativa vigente e presso gli uffici competenti, considerando unità e navigazione prevista.","In base al solo nome commerciale della barca."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000102',1) ON CONFLICT (question_id) DO NOTHING;
-- Source: https://rnli.org/water-safety/choose-your-activity/yacht-sailing-and-motorboating/how-to-stay-safe-when-you-go-afloat
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000103','41000000-0000-4000-8000-000000000001',3,'Come preparare il dispositivo individuale di galleggiamento prima di partire?','["Lasciarlo nella confezione per conservarlo.","Sceglierlo esclusivamente in base al colore.","Sceglierlo adatto alla persona, controllarlo e indossarlo correttamente."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000103',2) ON CONFLICT (question_id) DO NOTHING;
