INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000104','41000000-0000-4000-8000-000000000001',4,'Quale controllo richiede un giubbotto di salvataggio?','["Controlli e manutenzione secondo il fabbricante.","Nessun controllo se non è mai stato usato.","Solo una verifica del colore esterno."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000104',0) ON CONFLICT (question_id) DO NOTHING;
