INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000105','41000000-0000-4000-8000-000000000001',5,'Dove tenere un mezzo per chiedere aiuto?','["Sempre a terra per non danneggiarlo.","Protetto dall’acqua e raggiungibile.","Nel gavone più lontano dal posto di guida."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000105',1) ON CONFLICT (question_id) DO NOTHING;
