INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000106','41000000-0000-4000-8000-000000000001',6,'Quale informazione è essenziale per farsi localizzare in emergenza?','["Il prezzo pagato per la barca.","La marca degli occhiali da sole.","La propria posizione."]'::jsonb) ON CONFLICT (id) DO NOTHING;
