INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000107','41000000-0000-4000-8000-000000000001',7,'A cosa serve il dispositivo di arresto del motore con cordino, sulle unità che lo prevedono?','["Ad arrestare il motore se il conducente si allontana dalla postazione o cade fuori bordo.","Ad aumentare la potenza disponibile.","A sostituire il giubbotto di salvataggio."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000107',0) ON CONFLICT (question_id) DO NOTHING;
-- Source: https://rnli.org/water-safety/choose-your-activity/yacht-sailing-and-motorboating/how-to-stay-safe-when-you-go-afloat
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000108','41000000-0000-4000-8000-000000000001',8,'Come usare il cordino di arresto del motore?','["Scollegarlo durante le manovre.","Verificarne il funzionamento e collegarlo al conducente secondo le istruzioni.","Legarlo a una parte fissa della barca per non perderlo."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000108',1) ON CONFLICT (question_id) DO NOTHING;
-- Source: https://rnli.org/water-safety/choose-your-activity/yacht-sailing-and-motorboating/how-to-stay-safe-when-you-go-afloat
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000109','41000000-0000-4000-8000-000000000001',9,'Perché predisporre un’ancora adatta all’unità e al luogo?','["Garantisce l’ormeggio in qualsiasi fondale e condizione.","Sostituisce ogni mezzo di comunicazione.","Può aiutare a limitare la deriva in caso di perdita della propulsione, se utilizzabile in sicurezza."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000109',2) ON CONFLICT (question_id) DO NOTHING;
