INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000110','41000000-0000-4000-8000-000000000001',10,'Un aiuto al galleggiamento è necessariamente progettato per girare una persona incosciente a faccia in su?','["No, non va confuso con un dispositivo con quella funzione specifica.","Sì, qualunque modello ha questa funzione.","Sì, se è di colore acceso."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000110',0) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.questionnaires (id,title,version,description,pass_percent,is_demo,is_active) VALUES ('41000000-0000-4000-8000-000000000002','Kayak e SUP · uscire preparati',1,'Vento, attrezzatura, comunicazioni e pianificazione di un’uscita a pagaia. Le indicazioni generali vanno adattate al luogo e alle ordinanze locali.',80,true,true) ON CONFLICT (id) DO NOTHING;
-- Source: https://rnli.org/safety/choose-your-activity/stand-up-paddle-boarding
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000201','41000000-0000-4000-8000-000000000002',1,'Quale vento è particolarmente insidioso per chi inizia a usare il SUP?','["Il vento da terra verso il largo.","Solo il vento che forma onde molto alte.","Nessun vento se la tavola è gonfiabile."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000201',0) ON CONFLICT (question_id) DO NOTHING;
-- Source: https://rnli.org/safety/choose-your-activity/stand-up-paddle-boarding
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000202','41000000-0000-4000-8000-000000000002',2,'Una superficie calma vicino alla spiaggia garantisce un rientro facile con vento da terra?','["Sì, basta rimanere in piedi.","No, il vento può allontanare rapidamente la tavola.","Sì, l’assenza di onde elimina la deriva."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000202',1) ON CONFLICT (question_id) DO NOTHING;
