INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000203','41000000-0000-4000-8000-000000000002',3,'Come scegliere un aiuto al galleggiamento per pagaiare?','["Il più grande disponibile, senza regolarlo.","Solo in base al colore della tavola.","Adatto alla propria taglia e all’attività, indossato correttamente."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000203',2) ON CONFLICT (question_id) DO NOTHING;
