INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000204','41000000-0000-4000-8000-000000000002',4,'Come portare un telefono durante l’uscita?','["In custodia impermeabile e accessibile.","Non protetto sul fondo del kayak.","Lasciandolo sul pontile."]'::jsonb) ON CONFLICT (id) DO NOTHING;
