INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000205','41000000-0000-4000-8000-000000000002',5,'Un leash per SUP è adatto indistintamente a qualsiasi ambiente?','["Sì, purché il cavo sia il più lungo possibile.","No: tipo e sgancio devono essere appropriati all’ambiente e alla formazione ricevuta.","Sì, tutti i leash sono equivalenti."]'::jsonb) ON CONFLICT (id) DO NOTHING;
