INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000206','41000000-0000-4000-8000-000000000002',6,'Qual è un buon primo passo per iniziare il SUP?','["Provare da soli nel tratto più esposto.","Imparare soltanto quando si è già al largo.","Una lezione per apprendere tecnica, risalita e valutazione dell’ambiente."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000206',2) ON CONFLICT (question_id) DO NOTHING;
