INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000207','41000000-0000-4000-8000-000000000002',7,'Cosa valutare oltre al meteo prima di pagaiare?','["Correnti, temperatura dell’acqua e caratteristiche del luogo.","Soltanto la temperatura dell’aria.","Solo il numero di persone in spiaggia."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000207',0) ON CONFLICT (question_id) DO NOTHING;
