INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000208','41000000-0000-4000-8000-000000000002',8,'Come scegliere percorso e durata di un’uscita?','["Sempre fino al punto più lontano visibile.","In base alle capacità del gruppo e alle condizioni previste.","In base alla velocità del partecipante più esperto."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000208',1) ON CONFLICT (question_id) DO NOTHING;
