INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000209','41000000-0000-4000-8000-000000000002',9,'Perché comunicare a qualcuno a terra il programma dell’uscita?','["Per evitare di controllare le condizioni.","Per poter lasciare a terra ogni comunicazione.","Per rendere noto il percorso e quando è previsto il rientro."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000209',2) ON CONFLICT (question_id) DO NOTHING;
