INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000210','41000000-0000-4000-8000-000000000002',10,'Quali condizioni del vento considerare nella pianificazione?','["Intensità e direzione, attuali e previste.","Solo la direzione al momento della partenza.","Solo le condizioni della settimana precedente."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('51000000-0000-4000-8000-000000000210',0) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.questionnaires (id,title,version,description,pass_percent,is_demo,is_active) VALUES ('41000000-0000-4000-8000-000000000003','Snorkeling · esplorare in sicurezza',1,'Scelta del sito, compagno, attrezzatura e condizioni del mare per lo snorkeling in superficie. Non abilita all’apnea profonda o alle immersioni con autorespiratore.',80,true,true) ON CONFLICT (id) DO NOTHING;
