INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000301','41000000-0000-4000-8000-000000000003',1,'Quale organizzazione raccomanda BSAC per un’uscita di snorkeling?','["Una coppia in acqua e una persona di sorveglianza a terra.","Una persona sola, purché esperta.","Un gruppo senza accordi o sorveglianza."]'::jsonb) ON CONFLICT (id) DO NOTHING;
