INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000302','41000000-0000-4000-8000-000000000003',2,'Prima di entrare in acqua, cosa controllare?','["Niente se l’attrezzatura è nuova.","Maschera, boccaglio e pinne.","Solo la carica della fotocamera."]'::jsonb) ON CONFLICT (id) DO NOTHING;
