INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000303','41000000-0000-4000-8000-000000000003',3,'Un cinghiolo della pinna danneggiato va ignorato per una breve uscita?','["Sì, vicino alla costa non conta.","Sì, se la pinna ha un colore visibile.","No, occorre risolvere il difetto prima dell’uscita."]'::jsonb) ON CONFLICT (id) DO NOTHING;
