INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000304','41000000-0000-4000-8000-000000000003',4,'Quale sito è preferibile per iniziare?','["Un luogo riparato, adatto alle capacità e con accessi agevoli.","Un canale con intenso traffico di barche.","Una scogliera senza possibilità di uscita."]'::jsonb) ON CONFLICT (id) DO NOTHING;
