INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000305','41000000-0000-4000-8000-000000000003',5,'Perché individuare un’uscita alternativa dall’acqua?','["Per non dover controllare l’ingresso.","Per poter interrompere l’attività se necessario.","Per prolungare sempre la distanza percorsa."]'::jsonb) ON CONFLICT (id) DO NOTHING;
