INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('51000000-0000-4000-8000-000000000307','41000000-0000-4000-8000-000000000003',7,'Quali informazioni consultare prima dell’uscita?','["Meteo e stato del mare.","Solo la temperatura prevista a mezzogiorno.","Solo le foto del luogo."]'::jsonb) ON CONFLICT (id) DO NOTHING;
