-- Source: https://www.watersafetynz.org/stay-safe/kayaking-and-stand-up-paddleboarding
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000209','42000000-0000-4000-8000-000000000002',9,'Perché comunicare a qualcuno a terra il programma dell’uscita?','["Per evitare di controllare le condizioni.","Per poter lasciare a terra ogni comunicazione.","Per rendere noto il percorso e quando è previsto il rientro."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000209',2) ON CONFLICT (question_id) DO NOTHING;
-- Source: https://www.watersafetynz.org/stay-safe/kayaking-and-stand-up-paddleboarding
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000210','42000000-0000-4000-8000-000000000002',10,'Quali condizioni del vento considerare nella pianificazione?','["Intensità e direzione, attuali e previste.","Solo la direzione al momento della partenza.","Solo le condizioni della settimana precedente."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000210',0) ON CONFLICT (question_id) DO NOTHING;
INSERT INTO public.questionnaires (id,title,version,description,pass_percent,is_demo,is_active) VALUES ('42000000-0000-4000-8000-000000000003','Snorkeling · esplorare in sicurezza',2,'Scelta del sito, compagno, attrezzatura e condizioni del mare per lo snorkeling in superficie. Non abilita all’apnea profonda o alle immersioni con autorespiratore.',80,true,true) ON CONFLICT (id) DO NOTHING;
-- Source: https://www.bsac.com/advice-and-support/club-support/snorkelling-support/snorkelling-tips/
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000301','42000000-0000-4000-8000-000000000003',1,'Quale organizzazione raccomanda BSAC per un’uscita di snorkeling?','["Una coppia in acqua e una persona di sorveglianza a terra.","Una persona sola, purché esperta.","Un gruppo senza accordi o sorveglianza."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000301',0) ON CONFLICT (question_id) DO NOTHING;
-- Source: https://www.bsac.com/advice-and-support/club-support/snorkelling-support/snorkelling-tips/
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000302','42000000-0000-4000-8000-000000000003',2,'Prima di entrare in acqua, cosa controllare?','["Niente se l’attrezzatura è nuova.","Maschera, boccaglio e pinne.","Solo la carica della fotocamera."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000302',1) ON CONFLICT (question_id) DO NOTHING;
-- Source: https://www.bsac.com/advice-and-support/club-support/snorkelling-support/snorkelling-tips/
INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000303','42000000-0000-4000-8000-000000000003',3,'Un cinghiolo della pinna danneggiato va ignorato per una breve uscita?','["Sì, vicino alla costa non conta.","Sì, se la pinna ha un colore visibile.","No, occorre risolvere il difetto prima dell’uscita."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000303',2) ON CONFLICT (question_id) DO NOTHING;
