INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000305','42000000-0000-4000-8000-000000000003',5,'Perché individuare un’uscita alternativa dall’acqua?','["Per non dover controllare l’ingresso.","Per poter interrompere l’attività se necessario.","Per prolungare sempre la distanza percorsa."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000305',1) ON CONFLICT (question_id) DO NOTHING;
