INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000306','42000000-0000-4000-8000-000000000003',6,'Quale condizione rende un sito inadatto a un principiante?','["Un accesso comodo.","Una zona riparata adeguata al gruppo.","Correnti pericolose."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000306',2) ON CONFLICT (question_id) DO NOTHING;
