INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000307','42000000-0000-4000-8000-000000000003',7,'Quali informazioni consultare prima dell’uscita?','["Meteo e stato del mare.","Solo la temperatura prevista a mezzogiorno.","Solo le foto del luogo."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000307',0) ON CONFLICT (question_id) DO NOTHING;
