INSERT INTO public.questionnaire_questions (id,questionnaire_id,position,prompt,options) VALUES ('52000000-0000-4000-8000-000000000308','42000000-0000-4000-8000-000000000003',8,'Come considerare maree e correnti locali nella pianificazione?','["Considerarle uguali in tutto il Mediterraneo.","Valutarle per il sito e l’orario scelti.","Ignorarle perché si resta in superficie."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questionnaire_answer_keys (question_id,correct_option) VALUES ('52000000-0000-4000-8000-000000000308',1) ON CONFLICT (question_id) DO NOTHING;
